#include "zp_c/rand.h"

#include "zp_c/fatal.h"

#include <sys/random.h>

// =========================================================================================================================================
// =========================================================================================================================================
// rand_u64_z: Generate a random 64-bit unsigned integer using getrandom().
// =========================================================================================================================================
// =========================================================================================================================================
uint64_t rand_u64_z(void)
{
    uint64_t value;
    ssize_t result = getrandom(&value, sizeof(value), 0);
    fatal_check_bool_z(result == sizeof(value), "getrandom failed");
    return value;
}

